from fastapi.sse import ServerSentEvent
from pydantic import ValidationError

def test_sse_multiline_id():
    try:
        ServerSentEvent(id="line1\nline2")
    except (ValueError, ValidationError):
        print("Caught expected error for multiline id")
        return
    print("Failed: multiline id was accepted")

def test_sse_multiline_event():
    try:
        ServerSentEvent(event="line1\nline2")
    except (ValueError, ValidationError):
        print("Caught expected error for multiline event")
        return
    print("Failed: multiline event was accepted")

def test_sse_valid_id():
    try:
        ServerSentEvent(id="valid-id")
        print("Success: valid id accepted")
    except (ValueError, ValidationError) as e:
        print(f"Failed: valid id rejected: {e}")

def test_sse_valid_event():
    try:
        ServerSentEvent(event="valid-event")
        print("Success: valid event accepted")
    except (ValueError, ValidationError) as e:
        print(f"Failed: valid event rejected: {e}")

if __name__ == "__main__":
    test_sse_multiline_id()
    test_sse_multiline_event()
    test_sse_valid_id()
    test_sse_valid_event()

